namespace sv_4a8cc1833ca64d8086790de8f6a0061c.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_4a8cc1833ca64d8086790de8f6a0061c.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(ActiveSection == "Profile" ? "active" : "")" @onclick='() => ActiveSection = "Profile"'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(ActiveSection == "Notifications" ? "active" : "")" @onclick='() => ActiveSection = "Notifications"'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(ActiveSection == "Security" ? "active" : "")" @onclick='() => ActiveSection = "Security"'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(ActiveSection == "Appearance" ? "active" : "")" @onclick='() => ActiveSection = "Appearance"'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (IsLoading)
        {
            <div class="loading-spinner">Loading...</div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "Profile":
                    @RenderProfileSection()
                    break;
                case "Notifications":
                    @RenderNotificationsSection()
                    break;
                case "Security":
                    @RenderSecuritySection()
                    break;
                case "Appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(ToastMessage))
        {
            <div class="toast @ToastType">
                @ToastMessage
                <button class="toast-close" @onclick="DismissToast">✕</button>
            </div>
        }
    </main>
</div>

@code {
    private string ActiveSection { get; set; } = "Profile";
    private bool IsLoading { get; set; } = true;
    private string? ToastMessage { get; set; }
    private string ToastType { get; set; } = "success";

    // Profile state
    private UserProfile? _savedProfile;
    private string ProfileDisplayName { get; set; } = "";
    private string ProfileEmail { get; set; } = "";
    private string ProfileBio { get; set; } = "";
    private string ProfileAvatarUrl { get; set; } = "";

    // Notifications state
    private NotificationPrefs? _notificationPrefs;
    private bool EmailNotifications { get; set; }
    private bool PushNotifications { get; set; }
    private bool WeeklyDigest { get; set; }
    private List<string> MutedChannels { get; set; } = new();
    private List<string> AllChannels { get; set; } = new() { "general", "announcements", "updates", "marketing", "engineering" };

    // Security state
    private SecuritySettings? _securitySettings;
    private bool TwoFactorEnabled { get; set; }
    private bool ChangePasswordExpanded { get; set; }
    private string CurrentPassword { get; set; } = "";
    private string NewPassword { get; set; } = "";
    private string ConfirmPassword { get; set; } = "";
    private string? RevokeConfirmSessionId { get; set; }

    // Appearance state
    private AppearanceSettings? _appearanceSettings;
    private string Theme { get; set; } = "System";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly List<string> AvailableLanguages = new()
    {
        "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"
    };

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _savedProfile = await profileTask;
        LoadProfileFromSaved();

        _notificationPrefs = await notifTask;
        EmailNotifications = _notificationPrefs.EmailNotifications;
        PushNotifications = _notificationPrefs.PushNotifications;
        WeeklyDigest = _notificationPrefs.WeeklyDigest;
        MutedChannels = new List<string>(_notificationPrefs.MutedChannels);

        _securitySettings = await securityTask;
        TwoFactorEnabled = _securitySettings.TwoFactorEnabled;

        _appearanceSettings = await appearanceTask;
        Theme = _appearanceSettings.Theme;
        FontSize = _appearanceSettings.FontSize;
        Language = _appearanceSettings.Language;
        CompactMode = _appearanceSettings.CompactMode;
    }

    private void LoadProfileFromSaved()
    {
        if (_savedProfile is null) return;
        ProfileDisplayName = _savedProfile.DisplayName;
        ProfileEmail = _savedProfile.Email;
        ProfileBio = _savedProfile.Bio;
        ProfileAvatarUrl = _savedProfile.AvatarUrl;
    }

    private void ShowToast(string message, string type = "success")
    {
        ToastMessage = message;
        ToastType = type;
        _ = AutoDismissToast();
    }

    private async Task AutoDismissToast()
    {
        await Task.Delay(4000);
        ToastMessage = null;
        await InvokeAsync(StateHasChanged);
    }

    private void DismissToast() => ToastMessage = null;

    // === Profile ===
    private async Task SaveProfile()
    {
        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        LoadProfileFromSaved();
        ShowToast("Changes discarded.", "info");
    }

    // === Notifications ===
    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        ShowToast("Notification preferences saved!");
    }

    private void ToggleChannelMute(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    // === Security ===
    private async Task UpdatePassword()
    {
        if (NewPassword != ConfirmPassword)
        {
            ShowToast("Passwords do not match.", "error");
            return;
        }
        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }
        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
        ChangePasswordExpanded = false;
        ShowToast("Password updated successfully!");
    }

    private void ConfirmRevokeSession(string sessionId)
    {
        RevokeConfirmSessionId = sessionId;
    }

    private async Task RevokeSession()
    {
        if (RevokeConfirmSessionId is null) return;
        await SettingsService.RevokeSessionAsync(RevokeConfirmSessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        RevokeConfirmSessionId = null;
        ShowToast("Session revoked.");
    }

    private void CancelRevoke() => RevokeConfirmSessionId = null;

    // === Appearance ===
    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
        ShowToast("Appearance settings saved!");
    }

    // === Render Fragments ===
    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                @if (!string.IsNullOrWhiteSpace(ProfileAvatarUrl))
                {
                    <img src="@ProfileAvatarUrl" alt="Avatar" class="avatar-image" />
                }
                else
                {
                    <div class="avatar-placeholder">No Avatar</div>
                }
                <span class="avatar-url-label">@ProfileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="ProfileDisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="ProfileEmail" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="ProfileBio"></textarea>
            </div>

            <div class="form-group">
                <label for="avatarUrl">Avatar URL</label>
                <input id="avatarUrl" type="url" @bind="ProfileAvatarUrl" />
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <input type="checkbox" @bind="EmailNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <input type="checkbox" @bind="PushNotifications" class="toggle-switch" />
                </label>
                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <input type="checkbox" @bind="WeeklyDigest" class="toggle-switch" />
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in AllChannels)
                {
                    var isMuted = MutedChannels.Contains(channel);
                    <label class="channel-item">
                        <input type="checkbox" checked="@isMuted"
                               @onchange="e => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
                        <span>#@channel</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(ChangePasswordExpanded ? "▾" : "▸")</span>
                </button>
                @if (ChangePasswordExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPw">Current Password</label>
                            <input id="currentPw" type="password" @bind="CurrentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPw">New Password</label>
                            <input id="newPw" type="password" @bind="NewPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPw">Confirm Password</label>
                            <input id="confirmPw" type="password" @bind="ConfirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-group" style="margin-top: 1.5rem;">
                <label class="toggle-label">
                    <span>Two-Factor Authentication</span>
                    <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                    <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
                </label>
                @if (_securitySettings?.LastPasswordChange.HasValue == true)
                {
                    <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
                }
            </div>

            <h3>Active Sessions</h3>
            @if (_securitySettings?.Sessions?.Count > 0)
            {
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
