                    <div class="avatar-placeholder">No Avatar</div>
                }
                <span class="avatar-url-label">@ProfileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="ProfileDisplayName" />
