                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme" checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size" checked="@(FontSize == size)"
                                   @onchange="() => FontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="Language">
                    @foreach (var lang in AvailableLanguages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Compact Mode</span>
                    <input type="checkbox" @bind="CompactMode" class="toggle-switch" />
                </label>
            </div>

            <h3>Preview</h3>
            <div class="appearance-preview @Theme.ToLower() @FontSize.ToLower() @(CompactMode ? "compact" : "")">
                <div class="preview-header">Sample Header</div>
                <p class="preview-body">This is how your content will look with the selected settings. The theme is <strong>@Theme</strong>, font size is <strong>@FontSize</strong>, and compact mode is <strong>@(CompactMode ? "on" : "off")</strong>.</p>
                <button class="preview-btn">Sample Button</button>
            </div>

            <div class="button-group">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}
"}

