+        }
+        else
+        {
+            @switch (ActiveSection)
+            {
+                case "Profile":
+                    @RenderProfileSection()
+                    break;
+                case "Notifications":
+                    @RenderNotificationsSection()
+                    break;
+                case "Security":
+                    @RenderSecuritySection()
+                    break;
+                case "Appearance":
+                    @RenderAppearanceSection()
+                    break;
+            }
+        }
+
+        @if (!string.IsNullOrEmpty(ToastMessage))
+        {
+            <div class="toast @ToastType">
+                @ToastMessage
+                <button class="toast-close" @onclick="DismissToast">✕</button>
+            </div>
+        }
+    </main>
+</div>
+
+@code {
+    private string ActiveSection { get; set; } = "Profile";
+    private bool IsLoading { get; set; } = true;
+    private string? ToastMessage { get; set; }
+    private string ToastType { get; set; } = "success";
+
+    // Profile state
+    private UserProfile? _savedProfile;
+    private string ProfileDisplayName { get; set; } = "";
+    private string ProfileEmail { get; set; } = "";
+    private string ProfileBio { get; set; } = "";
+    private string ProfileAvatarUrl { get; set; } = "";
+
+    // Notifications state
+    private NotificationPrefs? _notificationPrefs;
+    private bool EmailNotifications { get; set; }
+    private bool PushNotifications { get; set; }
+    private bool WeeklyDigest { get; set; }
+    private List<string> MutedChannels { get; set; } = new();
+    private List<string> AllChannels { get; set; } = new() { "general", "announcements", "updates", "marketing", "engineering" };
+
+    // Security state
+    private SecuritySettings? _securitySettings;
+    private bool TwoFactorEnabled { get; set; }
+    private bool ChangePasswordExpanded { get; set; }
+    private string CurrentPassword { get; set; } = "";
+    private string NewPassword { get; set; } = "";
+    private string ConfirmPassword { get; set; } = "";
+    private string? RevokeConfirmSessionId { get; set; }
+
+    // Appearance state
+    private AppearanceSettings? _appearanceSettings;
+    private string Theme { get; set; } = "System";
+    private string FontSize { get; set; } = "Medium";
+    private string Language { get; set; } = "English";
+    private bool CompactMode { get; set; }
+
+    private static readonly List<string> AvailableLanguages = new()
+    {
+        "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"
+    };
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllSettings();
+        IsLoading = false;
+    }
+
+    private async Task LoadAllSettings()
+    {
+        var profileTask = SettingsService.GetProfileAsync();
+        var notifTask = SettingsService.GetNotificationPrefsAsync();
+        var securityTask = SettingsService.GetSecuritySettingsAsync();
+        var appearanceTask = SettingsService.GetAppearanceAsync();
+
+        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);
+
+        _savedProfile = await profileTask;
+        LoadProfileFromSaved();
+
+        _notificationPrefs = await notifTask;
+        EmailNotifications = _notificationPrefs.EmailNotifications;
+        PushNotifications = _notificationPrefs.PushNotifications;
+        WeeklyDigest = _notificationPrefs.WeeklyDigest;
+        MutedChannels = new List<string>(_notificationPrefs.MutedChannels);
+
+        _securitySettings = await securityTask;
+        TwoFactorEnabled = _securitySettings.TwoFactorEnabled;
+
+        _appearanceSettings = await appearanceTask;
+        Theme = _appearanceSettings.Theme;
+        FontSize = _appearanceSettings.FontSize;
+        Language = _appearanceSettings.Language;
+        CompactMode = _appearanceSettings.CompactMode;
+    }
+
+    private void LoadProfileFromSaved()
+    {
+        if (_savedProfile is null) return;
+        ProfileDisplayName = _savedProfile.DisplayName;
+        ProfileEmail = _savedProfile.Email;
+        ProfileBio = _savedProfile.Bio;
+        ProfileAvatarUrl = _savedProfile.AvatarUrl;
+    }
+
+    private void ShowToast(string message, string type = "success")
+    {
+        ToastMessage = message;
+        ToastType = type;
+        _ = AutoDismissToast();
+    }
+
+    private async Task AutoDismissToast()
+    {
+        await Task.Delay(4000);
+        ToastMessage = null;
+        await InvokeAsync(StateHasChanged);
+    }
+
+    private void DismissToast() => ToastMessage = null;
+
+    // === Profile ===
+    private async Task SaveProfile()
+    {
+        var profile = new UserProfile(ProfileDisplayName, ProfileEmail, ProfileAvatarUrl, ProfileBio);
+        await SettingsService.SaveProfileAsync(profile);
+        _savedProfile = profile;
+        ShowToast("Profile saved successfully!");
+    }
+
+    private void DiscardProfileChanges()
+    {
+        LoadProfileFromSaved();
+        ShowToast("Changes discarded.", "info");
+    }
+
+    // === Notifications ===
+    private async Task SaveNotificationPrefs()
+    {
+        var prefs = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
+        await SettingsService.SaveNotificationPrefsAsync(prefs);
+        _notificationPrefs = prefs;
+        ShowToast("Notification preferences saved!");
+    }
+
+    private void ToggleChannelMute(string channel, bool muted)
+    {
+        if (muted && !MutedChannels.Contains(channel))
+            MutedChannels.Add(channel);
+        else if (!muted)
+            MutedChannels.Remove(channel);
+    }
+
+    // === Security ===
+    private async Task UpdatePassword()
+    {
+        if (NewPassword != ConfirmPassword)
+        {
+            ShowToast("Passwords do not match.", "error");
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
+        {
+            ShowToast("Please fill in all password fields.", "error");
+            return;
+        }
+        await SettingsService.ChangePasswordAsync(CurrentPassword, NewPassword);
+        CurrentPassword = "";
+        NewPassword = "";
+        ConfirmPassword = "";
+        ChangePasswordExpanded = false;
+        ShowToast("Password updated successfully!");
+    }
+
+    private void ConfirmRevokeSession(string sessionId)
+    {
+        RevokeConfirmSessionId = sessionId;
+    }
+
+    private async Task RevokeSession()
+    {
+        if (RevokeConfirmSessionId is null) return;
+        await SettingsService.RevokeSessionAsync(RevokeConfirmSessionId);
+        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
+        RevokeConfirmSessionId = null;
+        ShowToast("Session revoked.");
+    }
+
+    private void CancelRevoke() => RevokeConfirmSessionId = null;
+
+    // === Appearance ===
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        _appearanceSettings = settings;
+        ShowToast("Appearance settings saved!");
+    }
+
+    // === Render Fragments ===
+    private RenderFragment RenderProfileSection() => __builder =>
+    {
+        <section class="settings-section">
+            <h2>Profile</h2>
+
+            <div class="avatar-preview">
+                @if (!string.IsNullOrWhiteSpace(ProfileAvatarUrl))
+                {
+                    <img src="@ProfileAvatarUrl" alt="Avatar" class="avatar-image" />
+                }
+                else
+                {
+                    <div class="avatar-placeholder">No Avatar</div>
+                }
+                <span class="avatar-url-label">@ProfileAvatarUrl</span>
+            </div>
+
+            <div class="form-group">
+                <label for="displayName">Display Name</label>
+                <input id="displayName" type="text" @bind="ProfileDisplayName" />
+            </div>
+
+            <div class="form-group">
+                <label for="email">Email</label>
+                <input id="email" type="email" @bind="ProfileEmail" />
+            </div>
+
+            <div class="form-group">
+                <label for="bio">Bio</label>
+                <textarea id="bio" rows="4" @bind="ProfileBio"></textarea>
+            </div>
+
+            <div class="form-group">
+                <label for="avatarUrl">Avatar URL</label>
+                <input id="avatarUrl" type="url" @bind="ProfileAvatarUrl" />
+            </div>
+
+            <div class="button-group">
+                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
+                <button class="btn btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
+            </div>
+        </section>
+    };
+
+    private RenderFragment RenderNotificationsSection() => __builder =>
+    {
+        <section class="settings-section">
+            <h2>Notifications</h2>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <span>Email Notifications</span>
+                    <input type="checkbox" @bind="EmailNotifications" class="toggle-switch" />
+                </label>
+                <label class="toggle-label">
+                    <span>Push Notifications</span>
+                    <input type="checkbox" @bind="PushNotifications" class="toggle-switch" />
+                </label>
+                <label class="toggle-label">
+                    <span>Weekly Digest</span>
+                    <input type="checkbox" @bind="WeeklyDigest" class="toggle-switch" />
+                </label>
+            </div>
+
+            <h3>Muted Channels</h3>
+            <div class="channel-list">
+                @foreach (var channel in AllChannels)
+                {
+                    var isMuted = MutedChannels.Contains(channel);
+                    <label class="channel-item">
+                        <input type="checkbox" checked="@isMuted"
+                               @onchange="e => ToggleChannelMute(channel, (bool)(e.Value ?? false))" />
+                        <span>#@channel</span>
+                    </label>
+                }
+            </div>
+
+            <div class="button-group">
+                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">Save Preferences</button>
+            </div>
+        </section>
+    };
+
+    private RenderFragment RenderSecuritySection() => __builder =>
+    {
+        <section class="settings-section">
+            <h2>Security</h2>
+
+            <div class="expandable-panel">
+                <button class="panel-header" @onclick="() => ChangePasswordExpanded = !ChangePasswordExpanded">
+                    <span>Change Password</span>
+                    <span class="expand-icon">@(ChangePasswordExpanded ? "▾" : "▸")</span>
+                </button>
+                @if (ChangePasswordExpanded)
+                {
+                    <div class="panel-body">
+                        <div class="form-group">
+                            <label for="currentPw">Current Password</label>
+                            <input id="currentPw" type="password" @bind="CurrentPassword" />
+                        </div>
+                        <div class="form-group">
+                            <label for="newPw">New Password</label>
+                            <input id="newPw" type="password" @bind="NewPassword" />
+                        </div>
+                        <div class="form-group">
+                            <label for="confirmPw">Confirm Password</label>
+                            <input id="confirmPw" type="password" @bind="ConfirmPassword" />
+                        </div>
+                        <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
+                    </div>
+                }
+            </div>
+
+            <div class="toggle-group" style="margin-top: 1.5rem;">
+                <label class="toggle-label">
+                    <span>Two-Factor Authentication</span>
+                    <span class="status-indicator @(TwoFactorEnabled ? "enabled" : "disabled")">
+                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
+                    </span>
+                    <input type="checkbox" @bind="TwoFactorEnabled" class="toggle-switch" />
+                </label>
+                @if (_securitySettings?.LastPasswordChange.HasValue == true)
+                {
+                    <p class="info-text">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
+                }
+            </div>
+
+            <h3>Active Sessions</h3>
+            @if (_securitySettings?.Sessions?.Count > 0)
+            {
+                <table class="sessions-table">
+                    <thead>
+                        <tr>
+                            <th>Device</th>
+                            <th>Location</th>
+                            <th>Last Active</th>
+                            <th>Action</th>
+                        </tr>
+                    </thead>
+                    <tbody>
+                        @foreach (var session in _securitySettings.Sessions)
+                        {
+                            <tr>
+                                <td>@session.Device</td>
+                                <td>@session.Location</td>
+                                <td>@session.LastActive.ToString("g")</td>
+                                <td>
+                                    @if (session != _securitySettings.Sessions[0])
+                                    {
+                                        <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevokeSession(session.Id)">
+                                            Revoke
+                                        </button>
+                                    }
+                                    else
+                                    {
+                                        <span class="current-badge">Current</span>
+                                    }
+                                </td>
+                            </tr>
+                        }
+                    </tbody>
+                </table>
+            }
+
+            @if (RevokeConfirmSessionId is not null)
+            {
+                <div class="modal-overlay">
+                    <div class="modal-dialog">
+                        <h4>Confirm Session Revocation</h4>
+                        <p>Are you sure you want to revoke this session? The user will be logged out on that device.</p>
+                        <div class="button-group">
+                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke Session</button>
+                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                        </div>
+                    </div>
+                </div>
+            }
+        </section>
+    };
+
+    private RenderFragment RenderAppearanceSection() => __builder =>
+    {
+        <section class="settings-section">
+            <h2>Appearance</h2>
+
+            <div class="form-group">
+                <label>Theme</label>
+                <div class="radio-group">
+                    @foreach (var theme in new[] { "Light", "Dark", "System" })
+                    {
+                        <label class="radio-label">
+                            <input type="radio" name="theme" value="@theme" checked="@(Theme == theme)"
+                                   @onchange="() => Theme = theme" />
+                            <span>@theme</span>
+                        </label>
+                    }
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label>Font Size</label>
+                <div class="radio-group">
+                    @foreach (var size in new[] { "Small", "Medium", "Large" })
+                    {
+                        <label class="radio-label">
+                            <input type="radio" name="fontSize" value="@size" checked="@(FontSize == size)"
+                                   @onchange="() => FontSize = size" />
+                            <span>@size</span>
+                        </label>
+                    }
+                </div>
+            </div>
+
+            <div class="form-group">
+                <label for="language">Language</label>
+                <select id="language" @bind="Language">
+                    @foreach (var lang in AvailableLanguages)
+                    {
+                        <option value="@lang">@lang</option>
+                    }
+                </select>
+            </div>
+
+            <div class="toggle-group">
+                <label class="toggle-label">
+                    <span>Compact Mode</span>
+                    <input type="checkbox" @bind="CompactMode" class="toggle-switch" />
+                </label>
+            </div>
+
+            <h3>Preview</h3>
+            <div class="appearance-preview @Theme.ToLower() @FontSize.ToLower() @(CompactMode ? "compact" : "")">
+                <div class="preview-header">Sample Header</div>
+                <p class="preview-body">This is how your content will look with the selected settings. The theme is <strong>@Theme</strong>, font size is <strong>@FontSize</strong>, and compact mode is <strong>@(CompactMode ? "on" : "off")</strong>.</p>
+                <button class="preview-btn">Sample Button</button>
+            </div>
+
+            <div class="button-group">
+                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
+            </div>
+        </section>
+    };
+}
+

arguments.file_text:
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 4rem);
    gap: 0;
}

/* Sidebar */
.settings-sidebar {
    width: 240px;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
    flex-shrink: 0;
}

.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-sidebar li {
    padding: 0.75rem 1.5rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    font-size: 0.95rem;
    color: #555;
    transition: all 0.2s;
    border-left: 3px solid transparent;
}

.settings-sidebar li:hover {
    background: #e9ecef;
    color: #333;
}

.settings-sidebar li.active {
    background: #e3f2fd;
    color: #1976d2;
    border-left-color: #1976d2;
    font-weight: 600;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Main content */
.settings-content {
    flex: 1;
    padding: 2rem 3rem;
    position: relative;
    max-width: 800px;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 1rem;
    font-size: 1.1rem;
    color: #555;
}

/* Form elements */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="url"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
    outline: none;
    border-color: #1976d2;
    box-shadow: 0 0 0 2px rgba(25, 118, 210, 0.1);
}

/* Buttons */
.button-group {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn {
    padding: 0.6rem 1.2rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: all 0.2s;
}

.btn-primary {
    background: #1976d2;
    color: #fff;
}

.btn-primary:hover {
    background: #1565c0;
}

.btn-secondary {
    background: #e0e0e0;
    color: #555;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.btn-danger {
    background: #d32f2f;
    color: #fff;
}

.btn-danger:hover {
    background: #b71c1c;
}

.btn-sm {
    padding: 0.35rem 0.75rem;
    font-size: 0.8rem;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f5f5f5;
    border-radius: 8px;
}

.avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #ddd;
}

.avatar-placeholder {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: #ddd;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
    color: #777;
}

.avatar-url-label {
    font-size: 0.8rem;
    color: #777;
    word-break: break-all;
}

/* Toggle switches */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.toggle-label {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.6rem 0;
    cursor: pointer;
}

.toggle-label span:first-child {
    flex: 1;
    font-size: 0.95rem;
}

.toggle-switch {
    width: 20px;
    height: 20px;
    cursor: pointer;
}

/* Channel list */
.channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.5rem 0;
}

.channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    padding: 0.4rem 0;
}

.channel-item span {
    font-size: 0.9rem;
    color: #555;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
}

.panel-header {
    width: 100%;
    padding: 0.85rem 1.2rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 0.95rem;
    font-weight: 500;
}

.panel-header:hover {
    background: #e9ecef;
}

.expand-icon {
    font-size: 1rem;
}

.panel-body {
    padding: 1.2rem;
    border-top: 1px solid #e0e0e0;
}

/* Status indicators */
.status-indicator {
    font-size: 0.8rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-weight: 500;
}

.status-indicator.enabled {
    background: #e8f5e9;
    color: #2e7d32;
}

.status-indicator.disabled {
    background: #fbe9e7;
    color: #c62828;
}

.info-text {
    font-size: 0.85rem;
    color: #777;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.75rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.65rem 0.8rem;
    text-align: left;
    border-bottom: 1px solid #eee;
    font-size: 0.9rem;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #555;
}

.current-badge {
    font-size: 0.8rem;
    color: #1976d2;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: #fff;
    border-radius: 12px;
    padding: 2rem;
    max-width: 420px;
    width: 90%;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.modal-dialog p {
    color: #555;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.3rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

/* Appearance preview */
.appearance-preview {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    margin-top: 0.5rem;
    transition: all 0.3s;
}

.appearance-preview.dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.appearance-preview.light {
    background: #ffffff;
    color: #333;
}

.appearance-preview.system {
    background: #f5f5f5;
    color: #333;
}

.appearance-preview.small .preview-body {
    font-size: 0.8rem;
}

.appearance-preview.medium .preview-body {
